"""1363 (#11 hit_reactions_directions): Record-Coverage-v1330.ps1 with directional stun cases. A plain sword hit gives the
player no full-body native state; only a stun does (state 14, hit_react_stun_*, presented on the partner as stun
variants 1-4). Guard fights stunned the player in 4 of about 25 takes and only from some directions, so these cases stun
the source deterministically with its own grenade (the native self-stun of stun-network-v61b): granted a grenade, the
source looks down (pitch 75), throws it at its feet, then turns with the native look stick (RightX 32767) by 0, 90 right,
90 left or 180 degrees before it explodes, so the blast comes from the front, right, left or back. The source's health
is held by the lab. Each case records the partner's stun variants and weights, the source's native stun state and its
turn; it passes when the partner presents a stun at full weight. Generated by make_coverage_v1363.py."""
from pathlib import Path
N = Path(__file__).resolve().parent
src = (N / 'Record-Coverage-v1330.ps1').read_bytes().decode('utf-8')
crlf = '\r\n' in src
s = src.replace('\r\n', '\n')
def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:90])
    s = s.replace(old, new)

rep("# 1330 (#11, ranged and item completion):", "# 1363 (#11 hit_reactions_directions): stunfront/stunright/stunleft/stunback stun the source with its own grenade, turned\n# by the look stick before the blast. Generated by make_coverage_v1363.py.\n# 1330 (#11, ranged and item completion):")
rep("}elseif($case-in'crouchheavy','mana','pistol','crossbow','grenade','stunmine','springrazor','heart','health','manaelixir'){",
    "}elseif($case-in'crouchheavy','mana','pistol','crossbow','grenade','stunmine','springrazor','heart','health','manaelixir','stunfront','stunright','stunleft','stunback'){")
rep("if($case-notin'kick','crouchheavy','note','mana','stairs','pistol','crossbow','grenade','stunmine','springrazor','heart','health','manaelixir'){",
    "if($case-notin'kick','crouchheavy','note','mana','stairs','pistol','crossbow','grenade','stunmine','springrazor','heart','health','manaelixir','stunfront','stunright','stunleft','stunback'){")
rep("grenade=9500;", "grenade=9500;stunfront=10500;stunright=10500;stunleft=10500;stunback=11500;")
rep("     grenade=@(@(800,'grant','grenade'),@(3000,'lt',1300));\n",
    "     grenade=@(@(800,'grant','grenade'),@(3000,'lt',1300));\n"
    "     stunfront=@(@(600,'hold','on'),@(800,'grant','grenade'),@(2200,'pitch',65),@(3000,'lt',300),@(3400,'turn',0),@(7500,'pitch',0),@(9000,'hold','off'));\n"
    "     stunright=@(@(600,'hold','on'),@(800,'grant','grenade'),@(2200,'pitch',65),@(3000,'lt',300),@(3400,'turn',90),@(7500,'pitch',0),@(9000,'hold','off'));\n"
    "     stunleft=@(@(600,'hold','on'),@(800,'grant','grenade'),@(2200,'pitch',65),@(3000,'lt',300),@(3400,'turn',-90),@(7500,'pitch',0),@(9000,'hold','off'));\n"
    "     stunback=@(@(600,'hold','on'),@(800,'grant','grenade'),@(2200,'pitch',65),@(3000,'lt',300),@(3400,'turn',180),@(8500,'pitch',0),@(10000,'hold','off'));\n")
rep("'pitch'{& \"$PSScriptRoot/Set-ObserverPitch.ps1\" -Role $source -Pitch $d[2] -Quick|Out-Null}",
    "'pitch'{& \"$PSScriptRoot/Set-ObserverPitch.ps1\" -Role $source -Pitch $d[2] -Quick|Out-Null}"
    ";'hold'{C $source \"coop_player_health_hold $($d[2])\"};'turn'{$row.yawBefore=try{$vo=(Q $source '--player').nativeViewOrientation;[Math]::Round([Math]::Atan2([double]$vo[1],[double]$vo[0])*180/[Math]::PI,1)}catch{$null};if([int]$d[2]){& \"$lab/Send-D2Input.ps1\" -Role $source -RightX $(if([int]$d[2]-gt0){32767}else{-32767}) -DurationMs ([int]([Math]::Abs([int]$d[2])*1000/80))|Out-Null};$row.yawAfter=try{$vo=(Q $source '--player').nativeViewOrientation;[Math]::Round([Math]::Atan2([double]$vo[1],[double]$vo[0])*180/[Math]::PI,1)}catch{$null}}")
rep("useVariant=$mv.useVariant;useWeight=$mv.useWeight;", "useVariant=$mv.useVariant;useWeight=$mv.useWeight;stunVariant=$mv.stunVariant;stunWeight=$mv.stunWeight;")
rep("     'grenade'{$row.grenadeVariants=Shown 'grenadeWeight' 'grenadeVariant';",
    "     {$_-in'stunfront','stunright','stunleft','stunback'}{$row.stunVariants=Shown 'stunWeight' 'stunVariant';$row.sourceStunSamples=@($samples|Where-Object {@($_.active)-contains14}).Count\n"
    "      $row.expectedStun=@{stunfront=2;stunright=1;stunleft=3;stunback=4}[$case]\n"
    "      if(!@($row.stunVariants).Count){throw \"No stun presented (source stun samples $($row.sourceStunSamples))\"};$row.checks.Add(\"Stun presented: variants $($row.stunVariants-join ',') (expected $($row.expectedStun))\")}\n"
    "     'grenade'{$row.grenadeVariants=Shown 'grenadeWeight' 'grenadeVariant';")
rep("foreach($r in 'host','client'){try{I $r;C $r 'coop_observer_camera off';", "foreach($r in 'host','client'){try{I $r;C $r 'coop_player_health_hold off';C $r 'coop_observer_camera off';")  # a failed stun case must not leave the hold on
# pwsh -File passes a comma list as one string: split -Sources and -Cases right after the param line.
i = s.index('\n') + 1
s = s[:i] + "$Sources=@($Sources|ForEach-Object {$_-split','});$Cases=@($Cases|ForEach-Object {$_-split','})\n" + s[i:]
out = s.replace('\n', '\r\n') if crlf else s
(N / 'Record-Coverage-v1363.ps1').write_bytes(out.encode('utf-8'))
print('ok')
